-- GENERATED by `wfj generate` from data/quest/quest-0008.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [8080] = { nil, nil, nil, "Hai i Contrassegni d'Onore, {name}? La ⟦The League of Arathor=Lega di Arathor⟧ non può combattere una battaglia come si deve senza di loro...", "Hai il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle in fretta alle truppe.\n\nGrazie, {name}. In effetti, è con missioni riuscite come la tua che si vincono davvero le guerre.", nil, nil, nil, 0x37247045, 0x2c6df8ea, "mmm.." },
  [8105] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧!", "Assalta la miniera, la segheria, la fucina e la fattoria, poi torna dal primo maresciallo Oslight al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "{name}, la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ è una battaglia per le risorse e il territorio. I punti chiave della zona vanno tenuti e sfruttati per rifornire le nostre forze di materie prime e provviste di cui hanno gran bisogno. Ti ordino di assaltare i punti più lontani dalla nostra base nel ⟦Arathi Basin=Bacino d'Arathi⟧.\n\nAssalta la fattoria, la miniera, la segheria e la fucina quando sono controllate dal nemico. Trova lo stendardo nemico e strappalo dal pennone!\n\nQuando l'avrai fatto in tutti e quattro i punti, torna da me.", nil, "Mi sono giunti rapporti delle tue imprese nel ⟦Arathi Basin=Bacino d'Arathi⟧, {name}. Ben fatto! Con gente come te a unirsi alla lotta qui, ho fiducia che un giorno riconquisteremo la nostra patria.", 0xe8197bb2, 0x24235866, 0xc4127755, nil, 0x82cf24dd, "...m." },
  [8120] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧!", "Assalta la miniera, la segheria, la fucina e la stalla del ⟦Arathi Basin=Bacino d'Arathi⟧, poi torna dal maestro della morte Dwire a ⟦Hammerfall=Requie del Martello⟧.", "Come avrai di certo sentito, la Lega di Arathor sta mandando truppe numerose nel ⟦Arathi Basin=Bacino d'Arathi⟧. Affamati di cibo e provviste, quegli sciocchi dell'⟦Alliance=Alleanza⟧ intendono prendere e controllare le ricche risorse del luogo. Dobbiamo mostrar loro che Arathi non sarà mai più una casa per gli umani!\n\nVa' nel ⟦Arathi Basin=Bacino d'Arathi⟧ e assalta la miniera, la segheria, la fucina e le stalle. Abbatti gli stendardi nemici e reclama quei territori per l'⟦Horde=Orda⟧.\n\nVa', {name}. Fai rapporto da me quando avrai portato a termine il compito.", nil, "Un esploratore dei Profanatori mi ha portato il resoconto del tuo successo, {name}. Ben fatto.\n\nCome imparerai, per vincere la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ dobbiamo restare sempre vigili e schiacciare ogni tentativo di espansione dell'⟦Alliance=Alleanza⟧. Fallo, e la nostra vittoria qui è assicurata.", 0xe8197bb2, 0x5b64eb5f, 0xf3980fbf, nil, 0x1791a775, "...m." },
  [8123] = { "Tagliare i rifornimenti degli Arathor", "Vinci la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧, ottieni una ⟦Arathi Resource Crate=Cassa di Scorte d'Arathi⟧ e portala all'⟦Deathstalker=Inseguitore della Morte⟧ Mortis a ⟦Hammerfall=Requie del Martello⟧.", "La ⟦The League of Arathor=Lega di Arathor⟧ non bada a spese nel tentativo di riprendersi Arathi. Loro, e tutte le razze dell'⟦Alliance=Alleanza⟧, ora affluiscono in questa regione lontana, decisi ad allargare il loro dominio a partire dal ⟦Refuge Pointe=Fosso dei Rifugiati⟧. Dobbiamo fermarli, e il modo migliore per farlo è prendere le loro provviste.\n\nPuoi aiutarci, {name}. Entra nel ⟦Arathi Basin=Bacino d'Arathi⟧, noto per le sue ricche miniere, la terra fertile e gli abili artigiani. Conquista e controlla ogni base che puoi, vinci la battaglia e torna da me con le risorse che ottieni.", "Che c'è, {race}? Hai i Contrassegni d'Onore? Torna nel ⟦Arathi Basin=Bacino d'Arathi⟧, uccidi quei parassiti dell'⟦Alliance=Alleanza⟧ e impadronisciti delle loro risorse per la Dama Oscura!", "<L'⟦Deathstalker=Inseguitore della Morte⟧ Mortis sorride>\n\nUn altro colpo decisivo è stato inferto ai nostri nemici, {name}. Grazie alle tue gesta, il ⟦Arathi Basin=Bacino d'Arathi⟧ cadrà presto nelle mani dei Profanatori.", 0x7b8482f8, 0x81501782, 0xd18465ad, 0xd916acfe, 0x18a5b9a3, "....." },
  [8154] = { "Risorse del ⟦Arathi Basin=Bacino d'Arathi⟧!", "Vinci la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧, ottieni una ⟦Arathi Resource Crate=Cassa di Scorte d'Arathi⟧ e portala al sergente Maclear al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "La guerra si combatte con i soldati, te lo dirà qualunque soldato. Ma ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima di cominciare!\n\nEcco perché il ⟦Arathi Basin=Bacino d'Arathi⟧ è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname: servono tutti, e lì si possono ottenere tutti.\n\nÈ questo che voglio da te, {name}. Entra nel ⟦Arathi Basin=Bacino d'Arathi⟧, vinci la battaglia tenendo più basi del nemico e torna da me con una cassa di risorse.", "Hai i Contrassegni d'Onore, {name}? La ⟦The League of Arathor=Lega di Arathor⟧ non può combattere una battaglia come si deve senza di loro...", "Hai il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle in fretta alle truppe.\n\nGrazie, {name}. In effetti, è con missioni riuscite come la tua che si vincono davvero le guerre.", 0xa6f22932, 0x982ec307, 0xfe0a59ea, 0x37247045, 0x2c6df8ea, "....." },
  [8155] = { "Risorse del ⟦Arathi Basin=Bacino d'Arathi⟧!", "Vinci la battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧, ottieni una ⟦Arathi Resource Crate=Cassa di Scorte d'Arathi⟧ e portala al sergente Maclear al ⟦Refuge Pointe=Fosso dei Rifugiati⟧.", "La guerra si combatte con i soldati, te lo dirà qualunque soldato. Ma ti diranno anche che una battaglia combattuta con un equipaggiamento scadente o a stomaco vuoto è persa prima di cominciare!\n\nEcco perché il ⟦Arathi Basin=Bacino d'Arathi⟧ è importante. Nel bacino ci sono zone chiave che custodiscono risorse essenziali. Metalli, armi, cibo, legname: servono tutti, e lì si possono ottenere tutti.\n\nÈ questo che voglio da te, {name}. Entra nel ⟦Arathi Basin=Bacino d'Arathi⟧, vinci la battaglia tenendo più basi del nemico e torna da me con una cassa di risorse.", "Hai i Contrassegni d'Onore, {name}? La ⟦The League of Arathor=Lega di Arathor⟧ non può combattere una battaglia come si deve senza di loro...", "Hai il Contrassegno! Ottimo lavoro! Manderò le risorse ai nostri furieri, che potranno distribuirle in fretta alle truppe.\n\nGrazie, {name}. In effetti, è con missioni riuscite come la tua che si vincono davvero le guerre.", 0xa6f22932, 0x982ec307, 0xfe0a59ea, 0x37247045, 0x2c6df8ea, "....." },
